class SeatMap {
    enum Status { AVAILABLE, HELD, BOOKED }

    static class HoldResult {
        boolean success;
        String holdId; // null when rejected
        String message;
        HoldResult(boolean success, String holdId, String message) {
            this.success = success; this.holdId = holdId; this.message = message;
        }
    }

