    private final Map<String, Status> seatStatus = new LinkedHashMap<>();
    private final Map<String, String> seatHeldBy = new HashMap<>(); // seatId -> holdId
    private final Map<String, Hold> holds = new HashMap<>(); // holdId -> Hold
    private int holdCounter = 0;

    private static class Hold {
        List<String> seats;
        long expiresAt;
        Hold(List<String> seats, long expiresAt) { this.seats = seats; this.expiresAt = expiresAt; }
    }

    SeatMap(List<String> seatIds, int holdTtlSeconds) {
        this.holdTtlSeconds = holdTtlSeconds;
        for (String seatId : seatIds) seatStatus.put(seatId, Status.AVAILABLE);
    }

    private void releaseExpiredHolds(long currentTime) {
        List<String> expired = new ArrayList<>();
        for (Map.Entry<String, Hold> e : holds.entrySet()) {
            if (e.getValue().expiresAt <= currentTime) expired.add(e.getKey());
        }
        for (String holdId : expired) {
            Hold h = holds.remove(holdId);
            for (String seatId : h.seats) {
                seatStatus.put(seatId, Status.AVAILABLE);
                seatHeldBy.remove(seatId);
            }
        }
    }

    HoldResult requestHold(String customerId, List<String> seatIds, long currentTime) {
        releaseExpiredHolds(currentTime);

        for (String seatId : seatIds) {
            if (seatStatus.get(seatId) != Status.AVAILABLE) {
                String msg = customerId + ": REJECTED, entire group failed because " + seatId + " is not available (none held)";
                return new HoldResult(false, null, msg);
            }
        }

        String holdId = "hold-" + (++holdCounter);
        long expiresAt = currentTime + holdTtlSeconds;
        holds.put(holdId, new Hold(new ArrayList<>(seatIds), expiresAt));
        for (String seatId : seatIds) {
            seatStatus.put(seatId, Status.HELD);
            seatHeldBy.put(seatId, holdId);
        }
        String msg = customerId + ": HELD " + seatIds + " as " + holdId + " (expires at " + expiresAt + ")";
        return new HoldResult(true, holdId, msg);
    }

