class SeatMap:
    # A movie showtime's seat map: a customer requesting several specific seats
    # together either holds every one of them, if all are available, or none of
    # them at all, if even a single one is not. A held group auto-releases if its
    # own timer runs out before payment confirms it as a permanent booking.
    AVAILABLE = "AVAILABLE"
    HELD = "HELD"
    BOOKED = "BOOKED"

    def __init__(self, seat_ids, hold_ttl_seconds):
        self.hold_ttl_seconds = hold_ttl_seconds
        self.seat_status = {seat_id: self.AVAILABLE for seat_id in seat_ids}
        self.seat_held_by = {}  # seatId -> holdId
        self.holds = {}  # holdId -> {"seats": [...], "expiresAt": ...}
        self.hold_counter = 0

    def _release_expired_holds(self, current_time):
        expired = [hold_id for hold_id, h in self.holds.items() if h["expiresAt"] <= current_time]
        for hold_id in expired:
            h = self.holds.pop(hold_id)
            for seat_id in h["seats"]:
                self.seat_status[seat_id] = self.AVAILABLE
                self.seat_held_by.pop(seat_id, None)

    def request_hold(self, customer_id, seat_ids, current_time):
        self._release_expired_holds(current_time)

        for seat_id in seat_ids:
            if self.seat_status[seat_id] != self.AVAILABLE:
                message = f"{customer_id}: REJECTED, entire group failed because {seat_id} is not available (none held)"
                return {"success": False, "holdId": None, "message": message}

        self.hold_counter += 1
        hold_id = f"hold-{self.hold_counter}"
        expires_at = current_time + self.hold_ttl_seconds
        self.holds[hold_id] = {"seats": list(seat_ids), "expiresAt": expires_at}
        for seat_id in seat_ids:
            self.seat_status[seat_id] = self.HELD
            self.seat_held_by[seat_id] = hold_id
        message = f"{customer_id}: HELD {seat_ids} as {hold_id} (expires at {expires_at})"
        return {"success": True, "holdId": hold_id, "message": message}

    def confirm_booking(self, hold_id, current_time):
        self._release_expired_holds(current_time)
        h = self.holds.pop(hold_id, None)
        if h is None:
            return "CONFIRM FAILED: hold no longer exists (already expired)"
        for seat_id in h["seats"]:
            self.seat_status[seat_id] = self.BOOKED
            self.seat_held_by.pop(seat_id, None)
        return f"CONFIRMED {h['seats']} as permanent booking (holdId {hold_id})"

    def describe(self):
        return " ".join(f"{seat_id}={status}" for seat_id, status in self.seat_status.items())


def main():
    seat_map = SeatMap(["A1", "A2", "A3", "A4", "A5"], 300)  # 300-second hold window

    x_result = seat_map.request_hold("X", ["A1", "A2", "A3"], 100)  # all free, held together
    print(x_result["message"])
    y_result1 = seat_map.request_hold("Y", ["A3", "A4"], 150)       # A3 already held, entire request fails
    print(y_result1["message"])
    y_result2 = seat_map.request_hold("Y", ["A4", "A5"], 160)       # both free, held together
    print(y_result2["message"])

    print(seat_map.confirm_booking(x_result["holdId"], 200))  # confirms X's actual hold by its real id

    z_result1 = seat_map.request_hold("Z", ["A4", "A5"], 500)  # Y's hold expired by now, available again
    print(z_result1["message"])
    z_result2 = seat_map.request_hold("Z", ["A1"], 500)        # A1 permanently booked, never available again
    print(z_result2["message"])

    print("Final seat map:", seat_map.describe())


if __name__ == "__main__":
    main()

