#include <string>
#include <map>
#include <unordered_map>
using namespace std;

// A movie showtime's seat map: a customer requesting several specific seats
// together either holds every one of them, if all are available, or none of
// them at all, if even a single one is not. A held group auto-releases if its
// own timer runs out before payment confirms it as a permanent booking.
class SeatMap {
public:
    enum Status { AVAILABLE, HELD, BOOKED };

    struct HoldResult {
        bool success;
        string holdId; // empty when rejected
        string message;
    };

    SeatMap(const vector<string>& seatIds, int holdTtlSeconds) : holdTtlSeconds(holdTtlSeconds), holdCounter(0) {
        for (const auto& seatId : seatIds) seatStatus[seatId] = AVAILABLE;
    }

    HoldResult requestHold(const string& customerId, const vector<string>& seatIds, long long currentTime) {
        releaseExpiredHolds(currentTime);

        for (const auto& seatId : seatIds) {
            if (seatStatus[seatId] != AVAILABLE) {
                string msg = customerId + ": REJECTED, entire group failed because " + seatId + " is not available (none held)";
                return HoldResult{false, "", msg};
            }
        }

        holdCounter++;
        string holdId = "hold-" + to_string(holdCounter);
        long long expiresAt = currentTime + holdTtlSeconds;
        holds[holdId] = Hold{seatIds, expiresAt};
        for (const auto& seatId : seatIds) {
            seatStatus[seatId] = HELD;
            seatHeldBy[seatId] = holdId;
        }
        string msg = customerId + ": HELD " + joinSeats(seatIds) + " as " + holdId + " (expires at " + to_string(expiresAt) + ")";
        return HoldResult{true, holdId, msg};
    }

    string confirmBooking(const string& holdId, long long currentTime) {
        releaseExpiredHolds(currentTime);
        auto it = holds.find(holdId);
        if (it == holds.end()) {
            return "CONFIRM FAILED: hold no longer exists (already expired)";
        }
        Hold h = it->second;
        holds.erase(it);
        for (const auto& seatId : h.seats) {
            seatStatus[seatId] = BOOKED;
            seatHeldBy.erase(seatId);
        }
        return "CONFIRMED " + joinSeats(h.seats) + " as permanent booking (holdId " + holdId + ")";
    }

    string describe() {
        string result;
        for (const auto& entry : seatStatus) {
            result += entry.first + "=" + statusName(entry.second) + " ";
        }
        if (!result.empty()) result.pop_back();
        return result;
    }

private:
    struct Hold {
        vector<string> seats;
        long long expiresAt;
    };

    int holdTtlSeconds;
    map<string, Status> seatStatus; // ordered, mirrors insertion-like iteration for consistent output
    unordered_map<string, string> seatHeldBy;
    unordered_map<string, Hold> holds;
    int holdCounter;

    void releaseExpiredHolds(long long currentTime) {
        vector<string> expired;
        for (const auto& e : holds) {
            if (e.second.expiresAt <= currentTime) expired.push_back(e.first);
        }
        for (const auto& holdId : expired) {
            Hold h = holds[holdId];
            holds.erase(holdId);
            for (const auto& seatId : h.seats) {
                seatStatus[seatId] = AVAILABLE;
                seatHeldBy.erase(seatId);
            }
        }
    }

    static string statusName(Status s) {
        switch (s) {
            case AVAILABLE: return "AVAILABLE";
            case HELD: return "HELD";
            case BOOKED: return "BOOKED";
        }
        return "UNKNOWN";
    }

    static string joinSeats(const vector<string>& seats) {
        string result = "[";
        for (size_t i = 0; i < seats.size(); i++) {
            result += seats[i];
            if (i + 1 < seats.size()) result += ", ";
        }
        result += "]";
        return result;
    }
};

int main() {
    SeatMap seatMap({"A1", "A2", "A3", "A4", "A5"}, 300); // 300-second hold window

    SeatMap::HoldResult xResult = seatMap.requestHold("X", {"A1", "A2", "A3"}, 100); // all free, held together
    cout << xResult.message << endl;
    SeatMap::HoldResult yResult1 = seatMap.requestHold("Y", {"A3", "A4"}, 150);       // A3 already held, entire request fails
    cout << yResult1.message << endl;
    SeatMap::HoldResult yResult2 = seatMap.requestHold("Y", {"A4", "A5"}, 160);       // both free, held together
    cout << yResult2.message << endl;

    cout << seatMap.confirmBooking(xResult.holdId, 200) << endl; // confirms X's actual hold by its real id

    SeatMap::HoldResult zResult1 = seatMap.requestHold("Z", {"A4", "A5"}, 500); // Y's hold expired by now, available again
    cout << zResult1.message << endl;
    SeatMap::HoldResult zResult2 = seatMap.requestHold("Z", {"A1"}, 500);       // A1 permanently booked, never available again
    cout << zResult2.message << endl;

    cout << "Final seat map: " << seatMap.describe() << endl;

    return 0;
}

